def task_func(file):
    if not os.path.isfile(file) or not file.endswith('.csv'):
        return []
    try:
        subprocess.run(['split', '-l', '100', file, 'split_'], check=True, capture_output=True)
    except subprocess.CalledProcessError:
        return []
    split_files = sorted(glob.glob('split_*'))
    try:
        for sf in split_files:
            with open(sf, 'r') as f:
                lines = f.readlines()
            random.shuffle(lines)
            with open(sf, 'w') as f:
                f.writelines(lines)
    except Exception:
        return []
