def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    if not isinstance(python_version, str):
        raise TypeError("python_version must be a string")
    if not isinstance(path_to_append, str):
        raise TypeError("path_to_append must be a string")
    try:
        if sys.platform.startswith('win'):
            result = subprocess.run(['where', f'python{python_version}'], capture_output=True, text=True, check=True)
        else:
            result = subprocess.run(['which', f'python{python_version}'], capture_output=True, text=True, check=True)
        python_path = result.stdout.strip().split('\n')[0]
    except subprocess.CalledProcessError:
        raise RuntimeError(f"Python version {python_version} not found")
    sys.executable = python_path
    sys.path.append(path_to_append)
    return python_version

